import { contextBridge, ipcRenderer } from 'electron';

contextBridge.exposeInMainWorld('electronAPI', {
  // Example: ipcRenderer.invoke('some-channel', someArgument)
  // For now, we'll expose a simple way to send messages to the main process
  sendMessage: (channel: string, data: any) => ipcRenderer.send(channel, data),
  on: (channel: string, callback: (...args: any[]) => void) => ipcRenderer.on(channel, (event, ...args) => callback(...args)),
  once: (channel: string, callback: (...args: any[]) => void) => ipcRenderer.once(channel, (event, ...args) => callback(...args)),
  // More APIs will be added as needed
});

