HID_Report_t hidReport;

// =========================================================================
// Setup
// =========================================================================
void setup() {
  Serial.begin(115200);

  // Set button pins as inputs with pull-ups
  for (int i = 0; i < NUM_BUTTONS; i++) {
    pinMode(BUTTON_PINS[i], INPUT_PULLUP);
  }

  // Set knob button pins as inputs with pull-ups
  pinMode(KNOB1_BUTTON_PIN, INPUT_PULLUP);
  pinMode(KNOB2_BUTTON_PIN, INPUT_PULLUP);

  // Initialize HID subsystem with custom VID/PID and report descriptor
  HID().begin(_hidReportDescriptor, sizeof(_hidReportDescriptor), HID_ReportType::HID_ITF_GAMEPAD, MY_VID, MY_PID);

  // Attach interrupts for rotary encoders (if using RotaryEncoder library)
  // Ensure the pins (A0-A3) are interrupt-capable on Pro Micro.
  // For Pro Micro, all digital pins (0-13) and analog pins (A0-A3) can be used as external interrupt pins.
  attachInterrupt(digitalPinToInterrupt(encoder1.getPinA()), checkPosition1, CHANGE);
  attachInterrupt(digitalPinToInterrupt(encoder1.getPinB()), checkPosition1, CHANGE);
  attachInterrupt(digitalPinToInterrupt(encoder2.getPinA()), checkPosition2, CHANGE);
  attachInterrupt(digitalPinToInterrupt(encoder2.getPinB()), checkPosition2, CHANGE);

  Serial.println("Arduino Custom HID Device Ready.");
}

// =========================================================================
// Loop
// =========================================================================
void loop() {
  updateButtons();
  updateKnobs(); // Updates rotary encoder values
  // If using potentiometers, use updatePotentiometers() instead

  HID().SendReport(1, (uint8_t*)&hidReport, sizeof(hidReport)); // Send Report ID 1
  delay(10); // Small delay to prevent flooding the USB bus
}

// =========================================================================
// Update Functions
// =========================================================================

void updateButtons() {
  hidReport.buttons = 0; // Clear all button states
  for (int i = 0; i < NUM_BUTTONS; i++) {
    if (digitalRead(BUTTON_PINS[i]) == LOW) { // Button is pressed (pull-up logic)
      hidReport.buttons |= (1 << i); // Set the corresponding bit
    }
  }
  // Check Knob Push Buttons
  if (digitalRead(KNOB1_BUTTON_PIN) == LOW) {
    hidReport.buttons |= (1 << (NUM_BUTTONS + 0)); // Button 13
  }
  if (digitalRead(KNOB2_BUTTON_PIN) == LOW) {
    hidReport.buttons |= (1 << (NUM_BUTTONS + 1)); // Button 14
  }
}

// For Rotary Encoders
long newPosition1 = 0;
long newPosition2 = 0;

void IRAM_ATTR checkPosition1() {
  encoder1.tick();
}
void IRAM_ATTR checkPosition2() {
  encoder2.tick();
}

void updateKnobs() {
  // Update encoder positions
  encoder1.tick();
  encoder2.tick();

  long currentPosition1 = encoder1.getPosition();
  long currentPosition2 = encoder2.getPosition();

  if (newPosition1 != currentPosition1) {
    // Send relative change or absolute position
    // For this example, let's send absolute position, scaled.
    // Adjust scaling as needed based on desired range and encoder steps.
    hidReport.knob1Value = map(currentPosition1, -100, 100, -32767, 32767); // Example mapping
    newPosition1 = currentPosition1;
  }
  if (newPosition2 != currentPosition2) {
    hidReport.knob2Value = map(currentPosition2, -100, 100, -32767, 32767);
    newPosition2 = currentPosition2;
  }
}


// If you want to use potentiometers instead of rotary encoders:
