void updatePotentiometers() {
  // Read analog values (0-1023)
  int pot1Raw = analogRead(A0); // Example pin for Potentiometer 1
  int pot2Raw = analogRead(A1); // Example pin for Potentiometer 2

  // Map to 16-bit signed range (-32767 to 32767)
  hidReport.knob1Value = map(pot1Raw, 0, 1023, -32767, 32767);
  hidReport.knob2Value = map(pot2Raw, 0, 1023, -32767, 32767);
}
*/

