import { app, BrowserWindow, ipcMain } from 'electron';
import path from 'path';
import HID from 'node-hid'; // Import node-hid

let mainWindow: BrowserWindow | null;
let hidDevice: HID.HID | null = null;
const ARDUINO_VID = 0x1234; // My Arduino Vendor ID
const ARDUINO_PID = 0xEFBE; // My Arduino Product ID

function createWindow() {
  mainWindow = new BrowserWindow({
    width: 800,
    height: 600,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      nodeIntegration: false,
      contextIsolation: true,
    },
  });

  mainWindow.loadFile(path.join(__dirname, 'index.html'));

  // Open the DevTools.
  mainWindow.webContents.openDevTools();

  mainWindow.on('closed', () => {
    mainWindow = null;
    // Stop HID listening when the window is closed
    if (hidDevice) {
      hidDevice.close();
      hidDevice = null;
      console.log('HID device closed.');
    }
  });
}

app.whenReady().then(() => {
  createWindow();

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) {
      createWindow();
    }
  });
});

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') {
    app.quit();
  }
});

// =========================================================================
// HID Communication
// =========================================================================

ipcMain.handle('hid:getDevices', async () => {
  try {
    const devices = HID.devices();
    console.log('Found HID devices:', devices);
    return devices;
  } catch (error) {
    console.error('Error getting HID devices:', error);
    return [];
  }
});

ipcMain.on('hid:startListening', (event, { vid, pid }) => {
  if (hidDevice) {
    console.log('Already listening to a HID device.');
    mainWindow?.webContents.send('hid:status', 'Already listening.');
    return;
  }

  try {
    const devices = HID.devices();
    const targetDevice = devices.find(d => d.vendorId === vid && d.productId === pid);

    if (targetDevice && targetDevice.path) {
      hidDevice = new HID.HID(targetDevice.path);
      console.log(`Started listening to HID device: ${targetDevice.product}`);
      mainWindow?.webContents.send('hid:status', `Connected to ${targetDevice.product}`);

      hidDevice.on('data', (data: Buffer) => {
        // console.log('HID Data:', data);
        mainWindow?.webContents.send('hid:data', Array.from(data));
      });

      hidDevice.on('error', (err: any) => {
        console.error('HID Error:', err);
        mainWindow?.webContents.send('hid:status', `Error: ${err.message}`);
        if (hidDevice) {
          hidDevice.close();
          hidDevice = null;
        }
      });
    } else {
      console.log(`HID device with VID 0x${vid.toString(16)} and PID 0x${pid.toString(16)} not found.`);
      mainWindow?.webContents.send('hid:status', 'Device not found.');
    }
  } catch (error: any) {
    console.error('Error starting HID listening:', error);
    mainWindow?.webContents.send('hid:status', `Failed to connect: ${error.message}`);
  }
});

ipcMain.on('hid:stopListening', () => {
  if (hidDevice) {
    hidDevice.close();
    hidDevice = null;
    console.log('Stopped HID listening.');
    mainWindow?.webContents.send('hid:status', 'Disconnected.');
  } else {
    console.log('No HID device to stop listening to.');
    mainWindow?.webContents.send('hid:status', 'Not connected.');
  }
});

