import { createRoot } from 'react-dom/client';
import './index.css';

// Declare the 'electronAPI' on the Window object
declare global {
  interface Window {
    electronAPI: {
      getDevices: () => Promise<any[]>;
      startListening: (vid: number, pid: number) => void;
      stopListening: () => void;
      onHidData: (callback: (data: number[]) => void) => void;
      onHidStatus: (callback: (status: string) => void) => void;
    };
  }
}

const ARDUINO_VID = 0x1234;
const ARDUINO_PID = 0xEFBE;

const App = () => {
  const [hidStatus, setHidStatus] = useState('Disconnected');
  const [hidData, setHidData] = useState<number[]>([]);

  useEffect(() => {
    if (window.electronAPI) {
      window.electronAPI.onHidStatus((status: string) => {
        console.log('HID Status:', status);
        setHidStatus(status);
      });

      window.electronAPI.onHidData((data: number[]) => {
        // console.log('HID Data:', data);
        setHidData(data);
      });

      // Attempt to connect on mount
      window.electronAPI.startListening(ARDUINO_VID, ARDUINO_PID);
    }
  }, []);

  const handleConnect = () => {
    if (window.electronAPI) {
      window.electronAPI.startListening(ARDUINO_VID, ARDUINO_PID);
    }
  };

  const handleDisconnect = () => {
    if (window.electronAPI) {
      window.electronAPI.stopListening();
    }
  };

  const parseHidData = (data: number[]) => {
    if (data.length < 5) return 'Invalid data length'; // At least 2 bytes for buttons, 2x2 for knobs = 6 bytes
    // Assuming the report structure:
    // Byte 0-1: Buttons (uint16_t)
    // Byte 2-3: Knob1 (int16_t)
    // Byte 4-5: Knob2 (int16_t)

    const buttons = data[0] | (data[1] << 8); // Little-endian
    const knob1Value = data[2] | (data[3] << 8); // Little-endian
    const knob2Value = data[4] | (data[5] << 8); // Little-endian

    let buttonStates = '';
    for (let i = 0; i < 14; i++) { // Check for 12 main buttons + 2 knob buttons
      if ((buttons >> i) & 1) {
        buttonStates += `B${i + 1} `;
      }
    }

    return (
      <>
        <p>Buttons Pressed: {buttonStates || 'None'}</p>
        <p>Knob 1 Value: {knob1Value}</p>
        <p>Knob 2 Value: {knob2Value}</p>
      </>
    );
  };


  return (
    <div style={{ padding: '20px' }}>
      <h1>Stream Deck Controller</h1>
      <p>HID Device Status: <strong>{hidStatus}</strong></p>

      <div style={{ marginBottom: '20px' }}>
        <button onClick={handleConnect} disabled={hidStatus.includes('Connected')}>Connect Arduino</button>
        <button onClick={handleDisconnect} disabled={!hidStatus.includes('Connected')} style={{ marginLeft: '10px' }}>Disconnect Arduino</button>
      </div>

      <h2>Raw HID Data:</h2>
      {hidData.length > 0 ? (
        <pre>{JSON.stringify(hidData)}</pre>
      ) : (
        <p>Waiting for data...</p>
      )}

      {hidData.length > 0 && hidData[0] === 1 ? ( // Assuming Report ID 1 from Arduino
        <div>
          <h2>Parsed HID Data:</h2>
          {parseHidData(hidData.slice(1))} {/* Skip Report ID byte */}
        </div>
      ) : null}
    </div>
  );
};

const container = document.getElementById('root');
if (container) {
  const root = createRoot(container);
  root.render(<App />);
}

